<script setup lang="ts">
import {fitLatticeToPrint,printBridgeWarning,optimizeLatticeForPrint,analyzeLatticePrintability,formatLatticePrintReport,latticeSlicerHintsJson,type LatticePrintReport} from '../services/latticePrintSettings'
import {inspectPolygonMesh} from '../services/geometry/polygon'
import {MAX_WORKSPACE_SOURCE_LENGTH} from '../services/workspaceDocument'
import {solidTopology,facePlane} from '../services/directSolidTools'
import {resolveSketchSupport} from '../services/mainSketchAssociation'
import {jointOptions,saveCadJoint,readCadJoints,removeCadJoints} from '../services/cadJoints'
import {exportFacetedStep,importFacetedStep} from '../services/cadStep'
import {cadDrawing,downloadCad} from '../services/cadDrawing'
import {ref,computed,watch,onUnmounted} from 'vue'
import type {MeshData} from '../core/mesh'
import type {PickHit} from '../services/rendererContracts'
import {sceneBody,previewMeshes} from '../services/mainModeling'
import {patchMainSource} from '../services/mainSourceEditing'
import {computeCadOperation,computeCadInspection,cancelMainSolid} from '../services/mainSolidWorker'
import {storageKeys,storageGet,storageSet} from '../services/safeStorage'
import {parseDirectDocument,type DirectSketch,type DirectDocument} from '../services/directModeling'
import type {CadOptions,CadAction} from '../services/cadWorkbench'
import {isSpatialPattern,latticeStructureHint} from '../services/solidLightening'
import {LATTICE_MATERIALS,analyzeLatticeStrength,formatLatticeStrengthReport,weakSpotHighlightMeshes,feaMemberHighlightMeshes,compareLatticeVariants,type LatticeMaterialId,type LatticeLoadCase,type LatticeStrengthReport} from '../services/latticeStrengthAnalysis'
import {DEFAULT_PRINT_SERVICE,defaultCompressionScenario,defaultStrutSection,type StrutSectionKind} from '../services/latticeStrengthScenario'
const props=defineProps<{meshes:MeshData[];selection:number[];hit:PickHit|null;source:string;ready:boolean;locale:string;initialAction?:CadAction}>()
const emit=defineEmits<{apply:[source:string];preview:[meshes:MeshData[]|null];close:[]}>()
const label=(a:string,b:string)=>props.locale==='ru'?a:b
const actions:[CadAction,string,string][]=[['lighten','Облегчение / каркас','Lightening / lattice'],['texture','Текстура поверхности','Surface texture'],['union','Объединить','Union'],['difference','Вычесть','Difference'],['intersection','Пересечь','Intersection'],['loft','Loft — между профилями','Loft'],['sweep','Sweep — вдоль пути','Sweep'],['mirror','Зеркало','Mirror'],['pattern','Массив тел','Body pattern'],['align','Выровнять','Align'],['distribute','Распределить','Distribute'],['resize','Габариты','Dimensions'],['draft','Уклон','Draft'],['hole','Отверстие','Hole'],['thread','Резьба','Thread'],['joint','Соединение','Joint']]
const o=ref<CadOptions>({action:props.initialAction??'union',lightening:{pattern:'web',axis:'z',cell:8,rib:1.35,rim:2,bottom:.6,top:0,seed:42,jitter:.7,lineWidth:.45,perimeters:3,skin:0,step:1.2,openTop:false,diagonals:true,wallDepth:0,keepCore:false},texture:{pattern:'ribs',pitch:6,height:.4,angle:0,seed:42,detail:3,invert:false,origin:[0,0,0],u:[1,0,0],v:[0,1,0]},ids:[],sketches:[],axis:[0,0,1],origin:[0,0,0],amount:10,count:5,width:6,height:2,depth:10,pitch:1,secondary:10,mode:'min',pathId:'',profileIds:[]})
const sketches=ref<DirectSketch[]>([]),error=ref(''),busy=ref(false),info=ref('')
const jointMin=ref(-180),jointMax=ref(180)
function loadJoint(){const j=readCadJoints(props.source).find(j=>j.parent===props.selection[0]&&j.child===props.selection[1]);if(j){o.value.axis=[...j.axis] as [number,number,number];o.value.origin=[...j.origin] as [number,number,number];o.value.mode=j.kind;o.value.amount=j.position;jointMin.value=j.min;jointMax.value=j.max}}
const spatialMode=computed(()=>isSpatialPattern(o.value.lightening?.pattern??'web'))
const structureHint=computed(()=>o.value.lightening?latticeStructureHint(o.value.lightening.pattern):null)
watch(()=>o.value.lightening?.pattern,pattern=>{if(!pattern||!o.value.lightening||!isSpatialPattern(pattern))return;const strength=pattern==='octet'||pattern==='bcc';Object.assign(o.value.lightening,{cell:strength?12:10,rib:3.2,step:1.2,skin:pattern==='bone'?2.4:0,openTop:pattern==='bone',jitter:pattern==='bone'?.8:0,wallDepth:strength&&!(o.value.lightening.wallDepth??0)?3.6:o.value.lightening.wallDepth,keepCore:o.value.lightening.keepCore??false})})
const printSettings=ref({nozzle:.4,layer:.2,lines:3,skinLayers:3,maxBridge:10,openTop:true,maxOverhangDeg:50,minFeatureMm:.4,printSpeedMms:45,fanPct:100})
const printReport=ref<LatticePrintReport|null>(null)
const printAdvice=ref('')
const strengthMaterialId=ref<LatticeMaterialId>('pla')
const strengthLoadCase=ref<LatticeLoadCase>('compression')
const strengthForceN=ref(100)
const strengthSafety=ref(2)
const strengthScenarioId=ref('compression')
const strengthSectionKind=ref<StrutSectionKind>('circle')
const strengthSectionB=ref(2)
const strengthEccentricity=ref(0)
const strengthTempC=ref(23)
const strengthHumidity=ref(50)
const strengthInfillPct=ref(100)
const strengthPerimeters=ref(3)
const strengthPrintAxis=ref<'x'|'y'|'z'>('z')
const strengthCompare=ref(false)
const strengthMaterial=computed(()=>LATTICE_MATERIALS.find(m=>m.id===strengthMaterialId.value)??LATTICE_MATERIALS[0])
const lastLightenDoc=ref<DirectDocument|null>(null)
const lastLightenBody=ref<DirectDocument['bodies'][number]|null>(null)
const lastLightenOptions=ref<CadOptions['lightening']|null>(null)
const lastLightenVolumes=ref<{beforeMm3:number;afterMm3:number}|null>(null)
const lastStrengthReport=ref<LatticeStrengthReport|null>(null)

function strengthLoad(){return {case:strengthLoadCase.value,forceN:strengthForceN.value,safety:strengthSafety.value}}

function strengthScenario(){
 const force=strengthForceN.value, safety=strengthSafety.value
 const s=defaultCompressionScenario(force, safety)
 s.activeId=strengthScenarioId.value
 const rib=lastLightenOptions.value?.rib ?? o.value.lightening?.rib ?? 3.2
 const section=defaultStrutSection(rib)
 section.kind=strengthSectionKind.value
 section.eccentricity=strengthEccentricity.value
 if(strengthSectionKind.value==='rectangle' || strengthSectionKind.value==='tube') section.b=strengthSectionB.value
 s.section=section
 s.service={
  ...DEFAULT_PRINT_SERVICE,
  printAxis:strengthPrintAxis.value,
  temperatureC:strengthTempC.value,
  humidityPct:strengthHumidity.value,
  infill:Math.max(0.05, Math.min(1, strengthInfillPct.value/100)),
  perimeters:strengthPerimeters.value,
  minWallMm:Math.max(0.4, printSettings.value.nozzle*printSettings.value.lines*0.9),
  maxBridgeMm:printSettings.value.maxBridge,
 }
 return s
}

function publishLightenPreview(doc:DirectDocument, report:LatticeStrengthReport|null){
 const base=previewMeshes(doc)
 const markerMm=Math.max(1.2, (report?.meanStrutLengthMm??8)*0.18)
 const weak=report?weakSpotHighlightMeshes(report.weakSpots, markerMm):[]
 const fea=report?.feaMembers?.length?feaMemberHighlightMeshes(report.feaMembers, markerMm*0.85):[]
 const markers=[...weak, ...fea]
 emit('preview', markers.length? [...base, ...markers] : base)
}

function refreshStrengthHighlights(){
 if(!lastLightenDoc.value||!lastLightenBody.value||!lastLightenOptions.value)return
 try{
  const report=analyzeLatticeStrength(lastLightenBody.value,lastLightenOptions.value,strengthMaterial.value,strengthLoad(),lastLightenVolumes.value??undefined,strengthScenario())
  lastStrengthReport.value=report
  let text=formatLatticeStrengthReport(report,strengthMaterial.value,strengthLoad(),props.locale==='ru'?'ru':'en')
  if(strengthCompare.value){
   const cur=lastLightenOptions.value.pattern
   const alt=(cur==='octet'?'bcc':cur==='bcc'?'octet':'isogrid') as typeof cur
   const other=analyzeLatticeStrength(lastLightenBody.value,{...lastLightenOptions.value,pattern:alt},strengthMaterial.value,strengthLoad(),lastLightenVolumes.value??undefined,strengthScenario())
   const cmp=compareLatticeVariants(
    {label:String(cur),massProxy:report.relativeDensity,stiffnessProxy:report.relativeStiffness,utilization:report.utilization??1,bucklingRatio:report.bucklingRatio??0.01},
    {label:String(alt),massProxy:other.relativeDensity,stiffnessProxy:other.relativeStiffness,utilization:other.utilization??1,bucklingRatio:other.bucklingRatio??0.01},
   )
   text+='\n'+(props.locale==='ru'?cmp.summary.ru:cmp.summary.en)
   for(const row of cmp.rows) text+=`\n  ${row.metric}: ${row.a.toFixed(3)} vs ${row.b.toFixed(3)} (Δ ${row.deltaPct.toFixed(1)}%)`
  }
  info.value=(info.value.split('\n')[0]??'')+'\n'+text
  publishLightenPreview(lastLightenDoc.value, report)
 }catch(e){info.value=(info.value.split('\n')[0]??'')+'\n'+String(e)}
}
watch(strengthScenarioId, id => {
 if (id === 'compression' || id === 'tension' || id === 'bending') strengthLoadCase.value = id
})
watch([strengthMaterialId,strengthLoadCase,strengthForceN,strengthSafety,strengthScenarioId,strengthSectionKind,strengthSectionB,strengthEccentricity,strengthTempC,strengthHumidity,strengthInfillPct,strengthPerimeters,strengthPrintAxis,strengthCompare],()=>{if(lastLightenDoc.value)refreshStrengthHighlights()})


function fitPrint(){try{if(o.value.lightening){o.value.lightening=fitLatticeToPrint(o.value.lightening,printSettings.value);strengthPrintAxis.value=(o.value.lightening.axis??'z') as 'x'|'y'|'z';strengthPerimeters.value=printSettings.value.lines;strengthInfillPct.value=Math.max(strengthInfillPct.value,40);printReport.value=analyzeLatticePrintability(o.value.lightening,printSettings.value);printAdvice.value=formatLatticePrintReport(printReport.value,props.locale==='ru'?'ru':'en')}}catch(e){error.value=String(e)}}
function optimizePrint(){try{if(!o.value.lightening)return;const r=optimizeLatticeForPrint(o.value.lightening,printSettings.value,{reorient:true,shrinkBridges:true});o.value.lightening=r.options;strengthPrintAxis.value=(r.options.axis??'z') as 'x'|'y'|'z';strengthPerimeters.value=printSettings.value.lines;strengthInfillPct.value=Math.max(strengthInfillPct.value,40);printReport.value=r.report;printAdvice.value=formatLatticePrintReport(r.report,props.locale==='ru'?'ru':'en')+(r.changed.length?`\n${props.locale==='ru'?'Изменения':'Changes'}: ${r.changed.join(', ')}`:'')}catch(e){error.value=String(e)}}
function copySlicerHints(){try{if(!printReport.value&&o.value.lightening)printReport.value=analyzeLatticePrintability(o.value.lightening,printSettings.value);if(!printReport.value)return;const text=latticeSlicerHintsJson(printReport.value);navigator.clipboard?.writeText(text);info.value=(info.value.split('\n')[0]??'')+'\n'+(props.locale==='ru'?'Подсказки слайсера скопированы.':'Slicer hints copied.')}catch(e){error.value=String(e)}}
const textureFace=ref(false)
watch(textureFace,cancel)
const sectionZ=ref(0)
function stepExport(){try{downloadCad(exportFacetedStep(chosenBodies()),'application/step','model.step')}catch(e){error.value=String(e)}}
async function stepImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(!props.ready)throw Error('Build the current source first.');if(file.size>20_000_000)throw Error('STEP file exceeds 20 MB.');const bodies=importFacetedStep(await file.text());emit('apply',patchMainSource(props.source,props.meshes,{version:1,sketches:[],bodies:[...props.meshes.map(sceneBody),...bodies]}))}catch(e){error.value=String(e)}finally{input.value=''}}
const chosenBodies=()=>props.selection.map(i=>sceneBody(props.meshes[i],i))
function drawing(format:'svg'|'pdf'){try{const d=cadDrawing(chosenBodies(),sectionZ.value);downloadCad(d[format],format==='svg'?'image/svg+xml':'application/pdf','drawing.'+format)}catch(e){error.value=String(e)}}
async function inspection(){const ticket=++version;busy.value=true;error.value='';try{const report=await computeCadInspection(chosenBodies());if(ticket===version)info.value=report.map(p=>`${p.a} / ${p.b}: ${p.overlapMm3.toFixed(3)} mm³; gap ${p.gapMm.toFixed(3)} mm`).join('\n')}catch(e){if(ticket===version)error.value=String(e)}finally{if(ticket===version)busy.value=false}}
let version=0
function refresh(){const items=storageKeys('scad-main-sketches-v1:').flatMap(key=>{try{const anchor=JSON.parse(key.slice('scad-main-sketches-v1:'.length));if(anchor.entity)resolveSketchSupport(props.meshes,anchor);return parseDirectDocument(storageGet(key)??'').sketches}catch{return []}});sketches.value=[...new Map(items.map(s=>[s.id,s])).values()]}
refresh()
const selectionLabel=computed(()=>props.selection.map(i=>i+1).join(' → '))
function cancel(){version++;cancelMainSolid();busy.value=false;lastLightenDoc.value=null;lastLightenBody.value=null;lastLightenOptions.value=null;lastLightenVolumes.value=null;lastStrengthReport.value=null;emit('preview',null)}
watch(()=>o.value.action,a=>{o.value.mode=a==='mirror'?'copy':a==='hole'?'plain':a==='thread'?'internal':a==='joint'?'revolute':'min'});
watch(()=>props.source,cancel);watch(()=>props.selection,cancel,{deep:true});watch([jointMin,jointMax],cancel);watch(o,()=>{cancel();error.value='';info.value=''},{deep:true});onUnmounted(cancel)
function picked(){if(props.hit){o.value.origin=[...props.hit.point];o.value.axis=props.hit.normal.map(v=>-v) as [number,number,number]}}
async function calculate(apply=false){
 error.value='';if(!props.ready){error.value=label('Сначала соберите текущий код','Build the current source first');return}
 const ticket=++version;busy.value=true
 try{
  const before:DirectDocument={version:1,sketches:[],bodies:props.meshes.map(sceneBody)},options=JSON.parse(JSON.stringify({...o.value,ids:props.selection.map(String),sketches:sketches.value}))
  if(options.action==='texture'&&textureFace.value){const hit=props.hit;if(!hit||props.selection.length!==1||hit.meshIndex!==props.selection[0])throw Error('Pick a face on the selected body.');const b=before.bodies[hit.meshIndex],topology=solidTopology(b.mesh),face=topology.faces.find(f=>f.triangles.includes(hit.triangleIndex));if(!face)throw Error('Pick a planar face.');const plane=facePlane(b,face);options.texture={...options.texture,...plane,triangles:face.triangles}}
  const request=options.action==='joint'?jointOptions(props.source,before.bodies,options,jointMin.value,jointMax.value):options
  const d=await computeCadOperation(before,request);if(ticket!==version)return
  if(options.action==='lighten'&&options.lightening){const volume=(b:typeof d.bodies)=>b.filter(b=>options.ids.includes(b.id)).reduce((s,b)=>s+inspectPolygonMesh(b.mesh).signedVolumeMm3,0),old=volume(before.bodies),next=volume(d.bodies);let text=label('Уменьшение объёма: ','Volume reduction: ')+(100*(old-next)/old).toFixed(1)+'% · '+(old/1000).toFixed(2)+' → '+(next/1000).toFixed(2)+' cm³';let report:LatticeStrengthReport|null=null;try{const body=before.bodies.find(b=>options.ids.includes(b.id));if(body){report=analyzeLatticeStrength(body,options.lightening,strengthMaterial.value,strengthLoad(),{beforeMm3:old,afterMm3:next},strengthScenario());lastLightenBody.value=body;lastLightenOptions.value=options.lightening;lastLightenVolumes.value={beforeMm3:old,afterMm3:next};lastStrengthReport.value=report;text+='\n'+formatLatticeStrengthReport(report,strengthMaterial.value,strengthLoad(),props.locale==='ru'?'ru':'en')}}catch(e){text+='\n'+String(e)}info.value=text;if(!apply){lastLightenDoc.value=d;publishLightenPreview(d,report)}else{lastLightenDoc.value=null}}
  if(apply){emit('preview',null);const source=patchMainSource(props.source,props.meshes,d);if(source.length>MAX_WORKSPACE_SOURCE_LENGTH)throw Error(label('Результат превышает лимит исходника. Увеличьте размер ячеек / шаг или уменьшите детализацию.','Result exceeds source size limit. Increase cell size / pitch or reduce detail.'));emit('apply',options.action==='joint'?saveCadJoint(source,d.bodies,options,jointMin.value,jointMax.value):source);storageSet('scad-cad-last-operation',JSON.stringify(o.value))}else if(options.action!=='lighten')emit('preview',previewMeshes(d))
 }catch(e){if(e instanceof Error&&e.name==='AbortError')return;error.value=e instanceof Error?e.message:String(e)}finally{if(ticket===version)busy.value=false}
}
</script>
<template><aside class="cad-workbench" @keydown.stop><header><strong>{{ label('Операции CAD','CAD operations') }}</strong><button @click="cancel();emit('close')">×</button></header>
 <label>{{ label('Операция','Operation') }}<select v-model="o.action"><option v-for="a in actions" :key="a[0]" :value="a[0]">{{ label(a[1],a[2]) }}</option></select></label><p>{{ label('Порядок тел','Body order') }}: {{ selectionLabel || '—' }}</p>
 <template v-if="o.action==='lighten'&&o.lightening"><details><summary>{{ label('Настройки FDM-печати','FDM print settings') }}</summary><label>{{ label('Сопло, мм','Nozzle, mm') }}<select v-model.number="printSettings.nozzle"><option :value="0.25">0.25</option><option :value="0.4">0.4</option><option :value="0.6">0.6</option><option :value="0.8">0.8</option></select></label><label>{{ label('Высота слоя, мм','Layer height, mm') }}<input v-model.number="printSettings.layer" type="number" min="0.05" step="0.05"></label><label>{{ label('Минимум линий в стенке','Minimum wall lines') }}<input v-model.number="printSettings.lines" type="number" min="1" max="8"></label><label>{{ label('Минимум слоёв дна / крышки','Minimum floor / roof layers') }}<input v-model.number="printSettings.skinLayers" type="number" min="0" step="1"></label><label>{{ label('Допустимый мост, мм (из теста принтера)','Bridge limit, mm (printer test)') }}<input v-model.number="printSettings.maxBridge" type="number" min="1" step="1"></label><label><input v-model="printSettings.openTop" type="checkbox">{{ label('Открытый верх','Open top') }}</label><button @click="fitPrint">{{ label('Подогнать геометрию под печать','Fit geometry to print settings') }}</button><button @click="optimizePrint">{{ label('Оптимизировать под печать','Optimize for print') }}</button><button @click="copySlicerHints">{{ label('Копировать подсказки слайсера','Copy slicer hints') }}</button><label>{{ label('Макс. свес, °','Max overhang, °') }}<input v-model.number="printSettings.maxOverhangDeg" type="number" min="20" max="80" step="5"></label><label>{{ label('Мин. деталь, мм','Min feature, mm') }}<input v-model.number="printSettings.minFeatureMm" type="number" min="0.1" step="0.05"></label><label>{{ label('Скорость периметра, mm/s','Perimeter speed, mm/s') }}<input v-model.number="printSettings.printSpeedMms" type="number" min="10" max="120" step="5"></label><label>{{ label('Обдув, %','Fan, %') }}<input v-model.number="printSettings.fanPct" type="number" min="0" max="100" step="5"></label><pre v-if="printAdvice" class="hint" style="white-space:pre-wrap;max-height:12em;overflow:auto">{{ printAdvice }}</pre><p v-if="printBridgeWarning(o.lightening,printSettings)">{{ label('Размер проёма превышает заданный мост. Уменьшите ячейку или используйте поддержки.','Opening exceeds the bridge limit. Reduce cell size or use supports.') }}</p><p>{{ label('Подогнать: линии/слои и каналы по Z. Оптимизировать: ориентация, openTop, ужать ячейку/ребро под мост, отчёт по свесам/охлаждению. Подсказки слайсера — JSON (не профиль вендора). Мост по размеру ячейки, без траекторий — проверяйте в слайсере.','Fit: line/layer snaps and Z channels. Optimize: orientation, openTop, shrink cell/rib for bridges, overhang/cooling report. Slicer hints are JSON (not a vendor profile). Bridge uses cell size, not toolpaths — verify in a slicer.') }}</p></details><label>{{ label('Структура','Structure') }}<select v-model="o.lightening.pattern"><option value="octet">{{ label('Октет-ферма ★ жёсткость/масса','Octet truss ★ stiffness/weight') }}</option><option value="isogrid">{{ label('Изогрид ★ стенки','Isogrid ★ walls') }}</option><option value="bcc">{{ label('ОЦК / BCC — сжатие','BCC — compression') }}</option><option value="bone">{{ label('Кость — объёмная пористость','Bone — organic porosity') }}</option><option value="spatial">{{ label('3D узлы и стержни','3D nodes and struts') }}</option><option value="grid">{{ label('Прямоугольная сетка','Grid') }}</option><option value="triangles">{{ label('Диагональный каркас','Diagonal skeleton') }}</option><option value="honeycomb">{{ label('Соты','Honeycomb') }}</option><option value="web">{{ label('Случайная паутина','Random web') }}</option></select></label><p v-if="structureHint" class="hint">{{ label(structureHint.ru,structureHint.en) }}</p><details open><summary>{{ label('Сопромат (оценка)','Strength of materials (estimate)') }}</summary><label>{{ label('Материал','Material') }}<select v-model="strengthMaterialId"><option v-for="m in LATTICE_MATERIALS" :key="m.id" :value="m.id">{{ label(m.ru,m.en) }} · E={{ m.E }} MPa</option></select></label><label>{{ label('Нагрузка','Load') }}<select v-model="strengthLoadCase"><option value="compression">{{ label('Сжатие','Compression') }}</option><option value="tension">{{ label('Растяжение','Tension') }}</option><option value="bending">{{ label('Изгиб','Bending') }}</option></select></label><label>{{ label('Сила, N','Force, N') }}<input v-model.number="strengthForceN" type="number" min="0.1" step="10"></label><label>{{ label('Запас прочности n','Safety factor n') }}<input v-model.number="strengthSafety" type="number" min="1" step="0.5"></label><label>{{ label('Кейс / комбинация','Case / combination') }}<select v-model="strengthScenarioId"><option value="compression">{{ label('Сжатие','Compression') }}</option><option value="tension">{{ label('Растяжение','Tension') }}</option><option value="bending">{{ label('Изгиб','Bending') }}</option><option value="pressure">{{ label('Давление на грань','Face pressure') }}</option><option value="distributed">{{ label('Распределённая нагрузка','Distributed load') }}</option><option value="uls">{{ label('ULS 1.2·сжатие+1.5·изгиб','ULS 1.2·comp+1.5·bend') }}</option></select></label><label>{{ label('Сечение стержня','Strut section') }}<select v-model="strengthSectionKind"><option value="circle">{{ label('Круг','Circle') }}</option><option value="square">{{ label('Квадрат','Square') }}</option><option value="rectangle">{{ label('Прямоугольник','Rectangle') }}</option><option value="tube">{{ label('Труба','Tube') }}</option></select></label><label v-if="strengthSectionKind==='rectangle'||strengthSectionKind==='tube'">{{ label('Вторая сторона / внутр. ⌀, мм','Second side / inner ⌀, mm') }}<input v-model.number="strengthSectionB" type="number" min="0.2" step="0.1"></label><label>{{ label('Эксцентриситет, мм','Eccentricity, mm') }}<input v-model.number="strengthEccentricity" type="number" min="0" step="0.1"></label><label>{{ label('Ось печати (=анизотропия)','Print axis (=anisotropy)') }}<select v-model="strengthPrintAxis"><option value="x">X</option><option value="y">Y</option><option value="z">Z</option></select></label><label>{{ label('Температура, °C','Temperature, °C') }}<input v-model.number="strengthTempC" type="number" step="1"></label><label>{{ label('Влажность, %','Humidity, %') }}<input v-model.number="strengthHumidity" type="number" min="0" max="100" step="5"></label><label>{{ label('Заполнение, %','Infill, %') }}<input v-model.number="strengthInfillPct" type="number" min="5" max="100" step="5"></label><label>{{ label('Периметры','Perimeters') }}<input v-model.number="strengthPerimeters" type="number" min="1" max="8" step="1"></label><label><input v-model="strengthCompare" type="checkbox"> {{ label('Сравнить с альтернативной решёткой (A/B)','Compare to alternate lattice (A/B)') }}</label><p class="hint">{{ label('Опоры/нагрузки по кейсу, ортотропия FDM (E∥/E⊥), сечение+эксцентриситет, truss FEA (δ, η, P/Pcr), гомогенизация ячейки, советы Δη. Слабые места и поле η подсвечиваются. Не сертификат и не solid FEA.','Case supports/loads, FDM orthotropy (E∥/E⊥), section+eccentricity, truss FEA (δ, η, P/Pcr), cell homogenization, Δη tips. Weak spots and η field are highlighted. Not certification or solid FEA.') }}</p></details><label v-if="!spatialMode">{{ label('Ось сквозных ячеек','Channel axis') }}<select v-model="o.lightening.axis"><option>x</option><option>y</option><option>z</option></select></label><label v-for="field in (spatialMode?[['cell','Ячейка','Cell'],['rib','Диаметр стержня','Strut diameter'],['lineWidth','Ширина линии печати','Extrusion width']]:[['cell','Ячейка','Cell'],['rib','Перемычка','Rib'],['rim','Рамка по габаритам','Bounding frame'],['bottom','Нижняя сплошная кожа','Bottom skin'],['top','Верхняя сплошная кожа','Top skin'],['lineWidth','Ширина линии печати','Extrusion width']])" :key="field[0]">{{ label(field[1],field[2]) }}, mm <input v-model.number="o.lightening[field[0] as 'cell'|'rib'|'rim'|'bottom'|'top'|'lineWidth']" type="number" min="0" step="0.1"></label><label>{{ label('Линий в перемычке','Lines per rib') }}<input v-model.number="o.lightening.perimeters" type="number" min="1" max="8"></label><button @click="o.lightening.rib=Math.ceil(o.lightening.rib/o.lightening.lineWidth)*o.lightening.lineWidth">{{ label('Округлить под линии печати','Round to extrusion lines') }}</button><template v-if="o.lightening.pattern==='web'||spatialMode"><label>Seed <input v-model.number="o.lightening.seed" type="number"></label><button @click="o.lightening.seed++">{{ label('Другой вариант','Next variation') }}</button><label>{{ label('Случайность','Randomness') }}<input v-model.number="o.lightening.jitter" type="range" min="0" max="1" step="0.05"></label></template><template v-if="spatialMode"><label>{{ label('Область сетки','Lattice region') }}<select :value="(o.lightening.wallDepth??0)>0?'walls':'volume'" @change="o.lightening.wallDepth=($event.target as HTMLSelectElement).value==='walls'?3.6:0"><option value="volume">{{ label('Весь объём','Whole volume') }}</option><option value="walls">{{ label('Только стенки','Walls only') }}</option></select></label><template v-if="(o.lightening.wallDepth??0)>0"><label>{{ label('Глубина скелетной стенки, мм','Skeletal wall depth, mm') }}<input v-model.number="o.lightening.wallDepth" type="number" min="0.1" step="0.2"></label><label>{{ label('Середина тела','Body interior') }}<select v-model="o.lightening.keepCore"><option :value="false">{{ label('Пустая','Hollow') }}</option><option :value="true">{{ label('Сплошная сердцевина','Solid core') }}</option></select></label><p>{{ label('Сетка ограничена слоем у всех поверхностей, включая дно и верх. Для открытых ячеек установите наружную оболочку 0.','Lattice is restricted to a surface layer, including floor and roof. Set outer skin to 0 for open cells.') }}</p></template><label>{{ label('Наружная оболочка, мм','Outer skin, mm') }}<input v-model.number="o.lightening.skin" type="number" min="0" step="0.2"></label><label>{{ label('Шаг расчёта, мм','Sampling step, mm') }}<input v-model.number="o.lightening.step" type="number" min="0.1" step="0.1"></label><label><input v-model="o.lightening.openTop" type="checkbox">{{ label('Открыть оболочку сверху (+Z)','Open skin on top (+Z)') }}</label><label v-if="o.lightening.pattern==='spatial'"><input v-model="o.lightening.diagonals" type="checkbox">{{ label('Диагональные связи','Diagonal connections') }}</label><p>{{ label('Октет и ОЦК — регулярные фермы с высокой удельной жёсткостью; режим «Только стенки» оставляет каркас в поверхностном слое. Кость — органическая пористость. Геометрия приближённая; прочность и печать без поддержек не сертифицируются.','Octet and BCC are regular high specific-stiffness trusses; Walls-only keeps the lattice in a surface band. Bone is organic porosity. Geometry is approximate; strength and support-free printing are not certified.') }}</p></template><p v-else>{{ label('Изогрид даёт равносторонние треугольные ячейки для стенок. Ячейки идут вдоль выбранной оси — для вертикальных каналов выбирайте Z. Верхняя кожа образует мосты. Это геометрическое облегчение без FEA.','Isogrid uses equilateral triangular wall cells. Channels follow the selected axis — use Z for vertical print channels. Top skin introduces bridges. Geometric lightening only, without FEA.') }}</p></template>
 <template v-if="o.action==='texture'&&o.texture"><label>{{ label('Рисунок','Pattern') }}<select v-model="o.texture.pattern"><option value="ribs">{{ label('Рёбра','Ribs') }}</option><option value="grooves">{{ label('Насечки','Grooves') }}</option><option value="knurl">{{ label('Ромбовая накатка','Diamond knurl') }}</option><option value="fuzzy">Fuzzy skin</option><option value="dimples">{{ label('Лунки','Dimples') }}</option><option value="waves">{{ label('Волны','Waves') }}</option></select></label><label><input v-model="textureFace" type="checkbox">{{ label('Только выбранная плоская грань','Picked planar face only') }}</label><label>{{ label('Шаг, мм','Pitch, mm') }}<input v-model.number="o.texture.pitch" type="number" min="0.1" step="0.5"></label><label>{{ label('Высота / глубина, мм','Height / depth, mm') }}<input v-model.number="o.texture.height" type="number" min="0.01" step="0.1"></label><label>{{ label('Угол, °','Angle, °') }}<input v-model.number="o.texture.angle" type="number" step="15"></label><label>{{ label('Детализация','Detail') }}<input v-model.number="o.texture.detail" type="number" min="3" max="8"></label><label v-if="o.texture.pattern==='fuzzy'">Seed<input v-model.number="o.texture.seed" type="number" step="1"></label><label><input v-model="o.texture.invert" type="checkbox">{{ label('Инвертировать рельеф','Invert relief') }}</label><p>{{ label('Настоящий рельеф для экспорта STL. Высота ≤ шага/4. На грани края остаются гладкими. Fuzzy skin меняет геометрию, а не траекторию печати.','Exportable geometry. Height ≤ pitch/4. Face borders stay smooth. Fuzzy skin changes geometry, not print toolpaths.') }}</p></template>
 <template v-if="['loft','sweep','pattern'].includes(o.action)"><button @click="refresh">{{ label('Обновить эскизы','Refresh sketches') }}</button><label v-if="o.action!=='pattern'">{{ label('Профили — в порядке выбора','Profiles in selection order') }}</label><label v-for="(s,i) in sketches.filter(s=>s.closed)" v-show="o.action!=='pattern'" :key="s.id"><input v-model="o.profileIds" :value="s.id" type="checkbox">{{ i+1 }} · {{ s.name }} · {{ s.points.length }}</label><label v-if="o.action!=='loft'">{{ label('Траектория','Path') }}<select v-model="o.pathId"><option value="">{{ label('Прямая по оси','Straight along axis') }}</option><option v-for="(s,i) in sketches.filter(s=>!s.closed)" :key="s.id" :value="s.id">{{ i+1 }} · {{ s.name }}</option></select></label></template>
 <template v-if="!['lighten','texture','union','difference','intersection','loft','sweep'].includes(o.action)"><label>{{ label('Направление XYZ','Direction XYZ') }}<input v-for="(_,i) in o.axis" :key="i" v-model.number="o.axis[i]" type="number" step="0.1"></label><label>{{ label('Опорная точка XYZ','Origin XYZ') }}<input v-for="(_,i) in o.origin" :key="i" v-model.number="o.origin[i]" type="number"></label><button :disabled="!hit" @click="picked">{{ label('Взять выбранную грань','Use picked face') }}</button></template>
 <label v-if="['pattern','draft','joint'].includes(o.action)">{{ label(o.action==='draft'?'Угол, °':o.action==='joint'?'Поворот, ° / ход, мм':'Шаг, мм','Angle / travel / spacing') }}<input v-model.number="o.amount" type="number"></label>
 <label v-if="o.action==='pattern'">{{ label('Количество','Count') }}<input v-model.number="o.count" type="number" min="2" max="100"></label>
 <label v-if="['hole','thread','resize'].includes(o.action)">{{ label(o.action==='resize'?'Размер X':'Диаметр','X size / Diameter') }}<input v-model.number="o.width" type="number" min="0.1"></label>
 <label v-if="['hole','resize'].includes(o.action)">{{ label(o.action==='resize'?'Размер Y':'Глубина выборки','Y size / Counterbore depth') }}<input v-model.number="o.height" type="number" min="0.1"></label>
 <label v-if="['hole','thread','resize'].includes(o.action)">{{ label(o.action==='resize'?'Размер Z':'Глубина / длина','Z size / Depth') }}<input v-model.number="o.depth" type="number" min="0.1"></label>
 <label v-if="o.action==='hole'">{{ label('Диаметр выборки','Counterbore diameter') }}<input v-model.number="o.secondary" type="number" min="0.1"></label><label v-if="o.action==='thread'">{{ label('Шаг резьбы','Thread pitch') }}<input v-model.number="o.pitch" type="number" min="0.1"></label>
 <label v-if="['mirror','align','distribute','hole','thread','joint'].includes(o.action)">{{ label('Режим','Mode') }}<select v-model="o.mode"><template v-if="o.action==='mirror'"><option value="copy">{{ label('Копия','Copy') }}</option><option value="replace">{{ label('Заменить','Replace') }}</option></template><template v-else-if="o.action==='hole'"><option value="plain">{{ label('Обычное','Plain') }}</option><option value="counterbore">{{ label('Цековка','Counterbore') }}</option><option value="countersink">{{ label('Зенковка','Countersink') }}</option></template><template v-else-if="o.action==='thread'"><option value="internal">{{ label('Внутренняя','Internal') }}</option><option value="external">{{ label('Наружная','External') }}</option></template><template v-else-if="o.action==='joint'"><option value="revolute">{{ label('Шарнир','Hinge') }}</option><option value="slider">{{ label('Ползун','Slider') }}</option></template><template v-else><option value="min">Min</option><option value="center">Center</option><option value="max">Max</option></template></select></label>
 <template v-if="o.action==='joint'"><label>Min <input v-model.number="jointMin" type="number">Max <input v-model.number="jointMax" type="number"></label><input v-model.number="o.amount" aria-label="Joint position" type="range" :min="jointMin" :max="jointMax" step="0.1"><button @click="loadJoint">{{ label('Загрузить соединение','Load joint') }}</button><button @click="emit('apply',removeCadJoints(source))">{{ label('Удалить соединения','Remove joints') }}</button><small>{{ label('Ось, положение и пределы сохраняются в исходнике. Изменение геометрии требует новой привязки.','Axis, position and limits are saved in source. Geometry changes require a new reference.') }}</small></template><details><summary>STEP · {{ label('Плоские грани','Faceted BREP') }}</summary><button @click="stepExport">{{ label('Экспорт STEP','Export STEP') }}</button><label>{{ label('Импорт STEP','Import STEP') }}<input type="file" accept=".step,.stp" @change="stepImport"></label><p>{{ label('Только FACETED_BREP. Аналитические поверхности и сборочные экземпляры пока не поддерживаются.','FACETED_BREP only. Analytic surfaces and assembly instances are not supported yet.') }}</p></details><details><summary>{{ label('Проверки и чертежи','Checks and drawings') }}</summary><button :disabled="busy" @click="inspection">{{ label('Пересечения и зазоры','Interference and clearance') }}</button><label>Z {{ label('сечения','section') }}<input v-model.number="sectionZ" type="number"></label><button @click="drawing('svg')">SVG</button><button @click="drawing('pdf')">PDF</button><p>{{ label('Три вида, габариты и сечение. Все рёбра видимы.','Three views, dimensions and section. All edges visible.') }}</p></details><footer><button :disabled="busy" @click="calculate()">{{ label('Предпросмотр','Preview') }}</button><button :disabled="busy" @click="calculate(true)">{{ label('Применить','Apply') }}</button><button @click="cancel">{{ label('Отмена','Cancel') }}</button></footer><p v-if="busy" role="status">{{ label('Расчёт…','Computing…') }}</p><p v-if="error" role="alert">{{ error }}</p><p v-if="info">{{ info }}</p>
 </aside></template>
<style scoped>.cad-workbench{position:absolute;left:10px;top:100px;z-index:7;width:330px;max-height:65%;overflow:auto;padding:10px;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:6px;font-size:12px}.cad-workbench header,.cad-workbench footer,.cad-workbench label{display:flex;align-items:center;gap:6px;margin:6px 0}.cad-workbench header{justify-content:space-between}.cad-workbench input[type=number]{width:55px}.cad-workbench button,.cad-workbench input,.cad-workbench select{font:inherit;background:var(--surface-raised);color:var(--text);border:1px solid var(--border);padding:5px;border-radius:4px}.cad-workbench select{min-width:0;max-width:240px}.cad-workbench [role=alert]{color:var(--danger)}.cad-workbench .hint{margin:4px 0 8px;line-height:1.4;color:var(--text-dim)}.cad-workbench [role=status],.cad-workbench p:last-of-type{white-space:pre-wrap}</style>
